"""Source scope and authored takeaways, not runtime facts or copied designs."""
SOURCES = []
def source(sid, title, url, kind, probes, takeaway, limit):
    SOURCES.append(dict(source_id=sid,title=title,url=url,kind=kind,probes=probes.split('|'),
        takeaway_ko=takeaway,claim_limit_ko=limit,review_date='2026-10-22'))

H='https://www.hplovecraft.com/'
def story(sid,title,code,probes,takeaway,limit):
    source(sid,title,H+'writings/texts/fiction/'+code+'.aspx','primary_fiction',probes,takeaway,limit)

source('S01','Notes on Writing Weird Fiction',H+'writings/texts/essays/nwwf.aspx','primary_author_essay','five definite|atmosphere|outsideness','현상의 바탕·영향·발현 매체·반응·주어진 조건의 결과를 나누면 추상 장르를 장면으로 번역하기 좋다.','다섯 항목은 저자의 서사론이며 모든 사진의 필수 구도나 관객 공포의 판정식은 아니다.')
source('S02','Supernatural Horror in Literature',H+'writings/texts/essays/shil.aspx','primary_author_essay','unknown|natural law','미지와 자연법칙에 대한 신뢰의 불안은 분위기와 연결된다.','특정 색·촉수·사망·패배가 장르의 필요조건이라는 근거가 아니다.')
story('S03','The Call of Cthulhu','cc','scaly body|non-Euclidean|bas-relief','우상·부조·조우한 본체의 묘사 대상을 분리한다. 르뤼에의 방향 혼란은 관찰자의 경험으로 서술된다.','우상의 모든 세부를 본체에 전사하거나 비유클리드 수학을 불가능한 계단과 동일시하지 않는다.')
story('S04','At the Mountains of Madness','mm','five-ridged|soapstone|protoplasmic','엘더 싱의 오중 구조와 쇼고스의 점성 덩어리는 별개다. 부조는 비인간 사회를 읽는 기록 매체다.','원전의 전 기관 수를 한 시점 사진에서 모두 입증할 수 있다고 보지 않는다. 허구의 진화사를 과학 사실로 취급하지 않는다.')
story('S05','The Colour out of Space','cs','spectrum|grey dust|orchard','관측되는 이상 스펙트럼, 비정상적 생장과 쇠약한 주변 환경은 서로 다른 증거다.','디스플레이의 자홍색 발광은 제작상 대안일 뿐 인간 가시역 밖의 색 자체를 재현했다는 뜻은 아니다.')
story('S06','The Whisperer in Darkness','wid','metal|sockets|crustaceous','미고의 갑각 유사 몸·막성 날개·안테나 머리와 금속 원통의 소켓·주변 기계를 구별한다.','원통 내부의 뇌는 원전 외관에서 보이지 않는다. 투명 유리병과 가시 뇌는 별도 creative_variant다.')
story('S07','The Shadow over Innsmouth','soi','fish|shoggoths|families','쇠락한 항구, 외형 변화, 거래와 가정의 강압적 질서는 층위가 다르다.','현실 민족·계급·얼굴을 종족 오염의 증거로 사용하지 않는다. 혈통과 동의는 피부 외형에서 확인되지 않는다.')
story('S08','The Shadow out of Time','sot','cones|handwriting|amnesia','원뿔 몸과 기능이 다른 말단, 기억 공백과 필적 증거를 분리한다.','단일 프레임의 비인간 몸은 정신 교환이나 시간 여행을 증명하지 않는다.')
story('S09','The Dunwich Horror','dh','Lavinia|Yog-Sothoth|powder','요그 소토스·문·차원과 가족의 출생 서사는 원전 문맥이다. 분말로 드러나는 윤곽은 선택한 순간의 매체다.','라비니아 임신의 구체적인 성행위·가해자·동의를 원전에서 확정할 수 있다고 하지 않는다.')
story('S10','The Dreams in the Witch House','dwh','angles|non-Euclidean|abysses','비정상적인 방의 각도와 학문적·주술적 탐구가 연결된다.','특정 각도 수치나 실제 고차원 이동 장치를 고정 디자인으로 만들지 않는다.')
story('S11','The Dream-Quest of Unknown Kadath','dq','night-gaunts|Nodens|Leng','꿈의 도시·렝·노덴스·무안면 생물은 아름다움과 위협이 공존하는 여정에 속한다.','드림랜드 전체를 폐허·검정·적대 존재로 고정하지 않는다. 렝의 지리를 통일 지도처럼 합치지 않는다.')
story('S12',"Pickman’s Model",'pm','photograph|rubber|ghoul','회화와 사진의 대응이 증거물로 기능한다.','사진 같은 외관만으로 기록의 진위·피사체의 실제 존재·정확한 생물 종을 판정하지 않는다.')
story('S13','The Music of Erich Zann','mez','window|viol|black','창문 경계와 연주 행위가 외부와의 관계를 조직한다.','켜는 자세는 정지 사진에서 보일 수 있지만 음정·음량·보호 효능·외부의 본질은 보이지 않는다.')
story('S14','The Haunter of the Dark','hd','Trapezohedron|Aklo|box','다각형 돌과 금속 상자, 어두운 교회와 기록은 서로 다른 소유자다.','수학적 정다면체나 고정 면 수를 작품 이름에서 자동 생성하지 않는다. 발광·예지·소환 효능을 외형과 분리한다.')
story('S15','History of the Necronomicon','hn','Al Azif|Alhazred|Latin','가공 저자·언어·번역·유통 이력을 갖춘 허구 서지다.','장정 재료·해골 문양·촘촘한 정본 문양은 본문에서 보장되지 않는다.')
story('S16','The Thing on the Doorstep','td','Asenath|body|handwriting','몸의 소유와 의식의 정체가 어긋나는 서사다.','겉모습·표정·성별로 의식의 진짜 소유자나 동의 여부를 판정하지 않는다.')
story('S17','The Rats in the Walls','rw','cattle|bones|pits','지하의 유골·사육 흔적과 가문의 발견이 결합한다.','유골의 종·친족·실제 섭식·역사적 원인은 별도 증거가 필요하다.')
story('S18','Herbert West—Reanimator','hwr','solution|dissect|head','주입 장치·시신·분리 신체와 반응이 서사에 등장한다.','주사기나 열린 눈은 생물학적 죽음·소생·재생의 입증이 아니다.')
story('S19','Nyarlathotep','n','instruments|screens|Egypt','시연자와 과학적인 장치, 관중의 관계가 한 작품의 발현 방식이다.','피부색·민족·파라오 의상을 모든 화신의 생물학적 표지로 만들지 않는다.')
story('S20','The Nameless City','nc','low|reptile|mummy','낮은 통로와 비인간 건설자의 몸 비례가 인간 중심 건축을 흔든다.','낮은 천장 하나가 비인간 문명·실제 연대의 증거는 아니다.')
story('S21','The Festival','f','green|church|procession','오래된 항구와 지하 의례로 내려가는 동선이 결합한다.','현실의 민속 행사나 종교를 외형만으로 악한 교단이라고 규정하지 않는다.')
story('S22','The Silver Key','sk','key|box|dream','열쇠라는 물건과 꿈·기억에 접근하는 서사적 역할을 분리한다.','은색 반사만으로 순은 재료나 차원 이동 기능을 판정하지 않는다.')
story('S23','The Loved Dead','ld','Eddy|dead|desires','C. M. Eddy Jr.와 러브크래프트의 협업·개작 맥락으로 표기한다. 성적 욕망과 죽음의 연결은 문학 분석 대상이다.','러브크래프트 단독작으로 기재하지 않는다. 시체 곁 인물만으로 시체성애를 판정하지 않는다.')
source('S24','Quotes Regarding the Necronomicon from Lovecraft’s Letters',H+'creation/necron/letters.aspx','primary_letters_transcribed','synthetic|written|invent','가공 신화와 책을 서로 인용하여 실재감이 커진 과정이 작가 편지에 드러난다.','실제 역사 문헌·초자연 효능·현대 시판 책과 동일성을 주장하지 않는다.')
source('S25','Fungi from Yuggoth — XXII Azathoth',H+'writings/texts/poetry/p289.aspx','primary_poetry','XXII|Azathoth|dreamed','꿈·우주 법칙·음악의 시적 연결을 읽는다.','우주 전체가 아자토스의 꿈이며 각성하면 소멸한다는 정설을 이 시에서 도출하지 않는다.')
source('S26','H. P. Lovecraft Misconceptions — Elder Sign',H+'life/myths.aspx','archive_editorial_with_letter_reference','pine|Elder Sign|1930','편지에 소개된 가지 모양 표식과 후대의 별 모양 관습을 구분한다.','편집자 설명을 편지 원본 도판의 정밀 획수 검증으로 승격하지 않는다. 이번 조사는 이미지 도판을 독립 계측하지 않았다.')
source('S27','The King in Yellow','https://www.gutenberg.org/cache/epub/8492/pg8492-images.html','primary_fiction_other_author','black stars|Hastur|onyx','체임버스의 가공 희곡·카르코사·표식은 별도 계보다. 검은 별과 너덜거리는 왕의 옷은 선택 가능한 문학 도상이다.','하스터=왕의 완전한 등식, 후대의 삼지 문양, 고정 괴물 해부학을 체임버스 정본으로 만들지 않는다.')
source('S28','The Cthulhu Mythos — Chaosium','https://cthulhuwiki.chaosium.com/the-mythos/','official_rpg_lore','Derleth|Outer Gods|Elder Gods','RPG의 신격 분류와 조사자 역할, 크툴루 신화 명칭의 계보를 확인한다.','RPG 분류를 러브크래프트 모든 원전에 동일하게 소급하지 않는다. 페이지의 삽화 복제 권리를 제공하는 출처가 아니다.')
source('S29','Sanity mechanic — Chaosium Q&A','https://www.chaosium.com/blogfrom-the-qa-what-is-the-sanity-san-mechanic-in-call-of-cthulhu/','official_game_design','resilience|mental illness|health','SAN은 조사자의 정신적 회복력을 나타내는 게임 장치로 다룬다.','실제 정신 건강 진단·얼굴 특징·정신질환의 시각적 지표로 사용하지 않는다.')
source('S30','SCP Glossary of Terms','https://scp-wiki.wikidot.com/glossary-of-terms','primary_community_definition','Cognitohazard|Infohazard','직접 인지와 정보 보유·전달 위험의 용례를 SCP 문맥으로 보존한다.','러브크래프트 원전 용어가 아니다. 무늬·책·공포 반응은 초자연적 감염의 입증이 아니다.')
source('S31','The Ballad of Black Tom — publisher','https://us.macmillan.com/books/9781250817556/theballadofblacktom/','publisher_description','Lovecraft|Red Hook|race','비판적 재서술의 사례로 작가·책·원작 관계를 확인한다.','서평·소개 페이지는 소설 전문이나 모든 퀴어·페미니즘 재해석의 정의가 아니다.')
source('S32','The Age of Lovecraft — publisher','https://www.upress.umn.edu/9780816699254/the-age-of-lovecraft/','academic_publisher_description','race|gender|weird','철학·인종·젠더·현대 위어드의 비평 질문을 확인한다.','책 소개만 읽었으므로 개별 장의 논증·Monstrous-Feminine 정의를 검증했다고 하지 않는다.')
source('S33','Euclidean and Non-Euclidean Geometry — course','https://www.math.brown.edu/bhassett/teaching/366spring03/366advert.html','university_course','parallel|hyperbolic|geometry','비유클리드 기하는 수학의 독립 주제다.','강의 개요는 불가능한 건축의 설계나 개별 수학 정리를 증명하지 않는다.')
source('S34','Cephalopods — Smithsonian Ocean','https://ocean.si.edu/ocean-life/invertebrates/octopuses-squids-and-relatives','museum_science','arms|tentacles|suckers','팔·촉수·흡반 배열은 생물별로 다르다. fictional tentacular에는 자동으로 오징어 해부학을 붙이지 않는다.','실제 두족류의 기관을 모든 외계 부속지의 필수 특징으로 일반화하지 않는다.')
source('S35','Characteristics of Fungi — OpenStax','https://openstax.org/books/biology-2e/pages/24-1-characteristics-of-fungi','textbook','hyphae|mycelium|fruiting','균사·균사체와 자실체를 나눈다.','fungoid는 형태 유사성일 수 있다. 버섯갓·감염·독성·발광은 필수 속성이 아니다.')
source('S36','Merriam-Webster — squamous','https://www.merriam-webster.com/dictionary/squamous','dictionary_publisher','scales|scaly','비늘형 표면의 뜻을 확인한다.','갑각·주름·점액·독성·물고기 종을 자동 함의하지 않는다.')
source('S37','American Heritage — rugose','https://ahdictionary.com/word/search.html?q=rugose','dictionary_publisher','wrinkled|rough','주름지거나 골이 있는 표면을 구분한다.','비늘 배열·노령·부패·특정 종을 뜻하지 않는다.')
source('S38','Cambridge Dictionary — ichor','https://dictionary.cambridge.org/us/dictionary/english/ichor','dictionary_publisher','gods|blood','신화의 신적 혈액이라는 어휘 뜻을 확인한다.','검정·점성·독성을 고정하지 않는다. 삼출액 용례의 독립 의학 검증은 하지 않았다.')
source('S39','Merriam-Webster — fetid','https://www.merriam-webster.com/dictionary/fetid','dictionary_publisher','odor|smell','냄새에 관한 어휘로 분류한다.','색·독성·감염·공포는 단어만으로 함의되지 않는다.')
source('S40','Merriam-Webster — ululation','https://www.merriam-webster.com/dictionary/ululation','dictionary_publisher','howl|wail','소리의 형태를 뜻하는 어휘로 분류한다.','입을 벌린 모습은 실제 소리나 사악한 의도·종교적 의미의 증거가 아니다.')
source('S41','Merriam-Webster — eldritch','https://www.merriam-webster.com/dictionary/eldritch','dictionary_publisher','weird|eerie','기이하고 섬뜩하다는 형용사 범위를 확인한다.','특정 색·해부학·미술 양식·신격의 이름이 아니다.')
source('S42','Tate — Abject art','https://www.tate.org.uk/art/art-terms/a/abject-art','museum_art_term','boundaries|body|disgust','몸의 경계와 금기·불편을 다루는 미술적 접근을 참고한다.','크리스테바 저서나 Monstrous-Feminine 이론 전체를 읽고 검증한 것이 아니다.')
source('S43','Tate — Sublime','https://www.tate.org.uk/art/art-terms/s/sublime','museum_art_term','awe|terror|greatness','압도적인 규모·경외와 공포의 미학적 관계를 참고한다.','작은 사람과 큰 건물 배치가 관객의 실제 숭고 경험을 증명하지 않는다.')
